const { Analysis, Device, Utils, Account, Services } = require("@tago-io/sdk");

async function myAnalysis(context, scope) {
    const env_vars = Utils.envToJson(context.environment);
    if (!env_vars.account_token) {
        return context.log("Missing account_token on environment parameters");
    }

    const account = new Account({ token: env_vars.account_token });
    const user_id = "66425cdf59aa3c0008518bc3";
    let accessValue = null; // Inicializado antes da ap

    const run = account.run;

    const result = await new Promise((resolve, reject) => {
        run.userInfo(user_id)
            .then((resultP) => {
                console.log("Pega=", resultP);
                resultP.tags.forEach(tag => {
                    if (tag.key === 'access') {
                        accessValue = tag.value; // Isso passa
                    }
                });
                resolve(accessValue); // Retorna o valor aqui
            })
            .catch((error) => {
                console.error("Erro:", error);
                reject(error);
            });
    });

    console.log("acessAfter:", accessValue);
    console.log("resultado:", result); // resultado aqui é 'admin'

    // Agora o acessoValue pode ser usado sem depender de .then externo
    if (result === 'admin') {
        console.log("Usuário é admin, fazer algo");
    }

    return result; // Retorna valor final
}

